[CmdletBinding()]param([string]$CommandName='help',[string]$Target='')
. (Join-Path $PSScriptRoot 'lib\runtime.ps1');Initialize-Module $PSScriptRoot
$Python=Join-Path $PSScriptRoot 'runtime\python\python.exe';$Gateway=Join-Path $PSScriptRoot 'service\ocr_job_gateway.py';$Port=9399;$Secrets=Join-Path $StateRoot 'secrets.json'
function Verify-Payload{Test-Payload;$env:PATH=(Join-Path $PSScriptRoot 'runtime\vc')+';'+(Split-Path $Python)+';'+$env:SystemRoot+'\System32';& $Python -c 'import paddle,paddleocr,paddlex; print("OCR archive imports OK")';if($LASTEXITCODE -ne 0){throw 'OCR archive import probe failed'};& $Python (Join-Path $PSScriptRoot 'service\test_ocr_job_gateway_contract.py');if($LASTEXITCODE -ne 0){throw 'OCR archive API contract failed'}}
function Install-Ocr{Begin-Install;Test-Payload;if(Test-Path $Secrets){$s=Read-Json $Secrets}else{$s=[ordered]@{token=New-HexSecret 32;gpu_index=0};Write-JsonAtomic $Secrets $s};& $Python (Join-Path $PSScriptRoot 'service\test_ocr_job_gateway_contract.py');if($LASTEXITCODE -ne 0){throw 'OCR API contract failed'};Write-Connection ([ordered]@{schema=1;module='paddleocr';url="http://127.0.0.1:$Port";token=$s.token;strict_gpu=$true});Start-Ocr;Stop-OwnedProcess 'paddleocr';Set-Installed;Write-Host '[OK] paddleocr installed; strict GPU pipeline passed'}
function Start-Ocr{$s=Read-Json $Secrets;$env:PATH=(Join-Path $PSScriptRoot 'runtime\vc')+';'+(Split-Path $Python)+';'+$env:SystemRoot+'\System32';$env:PADDLE_PDX_DISABLE_DEVICE_FALLBACK='1';$env:PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK='1';$env:PADDLE_PDX_CACHE_HOME=Join-Path $PSScriptRoot 'models';$env:LOCAL_OCR_GPU_INDEX=[string]$s.gpu_index;$env:LOCAL_OCR_TOKEN=$s.token;Start-OwnedProcess 'paddleocr' $Python @($Gateway,'--config',(Join-Path $PSScriptRoot 'service\pp-structure-v3-8gb.yaml'),'--model-root',(Join-Path $PSScriptRoot 'models'),'--jobs-root',(Join-Path $DataRoot 'jobs'),'--host','127.0.0.1','--port',$Port,'--token',$s.token) (Join-Path $PSScriptRoot 'service');Wait-Healthy 'paddleocr strict GPU API' {Test-Http "http://127.0.0.1:$Port/health"}}
switch($CommandName.ToLowerInvariant()){'install'{Install-Ocr}'start'{Assert-Installed;Start-Ocr}'stop'{Stop-OwnedProcess 'paddleocr'}'status'{Show-ModuleStatus @('paddleocr')}'verify'{Test-Payload;& $Python -c 'import paddle,paddleocr,paddlex; print("OCR imports OK")';if($LASTEXITCODE -ne 0){throw 'OCR imports failed'};if($Target -eq 'gpu'){Start-Ocr};Write-Host '[OK] paddleocr verified'}'verify-payload'{Verify-Payload}default{Write-Host 'Usage: MODULE.bat install|start|stop|status|verify [gpu]';if($CommandName -ne 'help' -and $CommandName){exit 2}}}
